const s=[{id:"P01",title:"Steel · 2007 · Correlates and theory of procrastination",url:"https://studypedia.au.dk/fileadmin/www.studiemetro.au.dk/Procrastination_2.pdf",type:"research",finding:"216 çalışmadan 691 korelasyon, ertelemeyi işin itici gelmesi, daha düşük öz denetim ve daha düşük öz yeterlikle ilişkilendirdi. Çalışma niyeti için r = -0,03’tü. Aralık sıfırı içeriyordu.",limitation:"Çoğunlukla öğrencilerle elde edilen ilişkisel kanıttır. Neden veya kişisel tanı değildir. Eski yaygınlık tahminleri bugünkü toplumu temsil eden güncel oranlar değildir."},{id:"P02",title:"Sirois & Pychyl · 2013 · Short-term mood regulation",url:"https://eprints.whiterose.ac.uk/91793/1/Compass%20Paper%20revision%20FINAL.pdf",type:"research",finding:"Kuramsal bir açıklamaya göre, işin yarattığı hoş olmayan duygulardan şimdi kaçmanın bedelini ileride ödersin.",limitation:"Bu, farklı araştırmaları ele alan bir anlatı derlemesidir. Yeni bir ortak etki büyüklüğü hesaplamaz. Her gecikmeyi açıklamaz, duyguyu adlandırmanın davranışı değiştirdiğini göstermez."},{id:"P03",title:"Gollwitzer & Sheeran · 2006 · If-then planning meta-analysis",url:"https://www.socmot.uni-konstanz.de/sites/default/files/06_Gollwitzer_Sheeran_Implementation_Intentions_And_Goal.pdf",type:"research",finding:"94 bağımsız testte, belirli “şu olursa bunu yaparım” planları hedefe ulaşmayı ortalama olarak artırdı. Bu eski derlemede standartlaştırılmış etki büyüklüğü d = 0,65’ti.",limitation:"Bulgular farklı hedeflerden ve eski çalışmalardan geliyor. Etki büyüklüğü, başarıda yüzde 65 artış demek değildir. Etki ertelemeye özgü de değildir. ODA’nın kısa iş alıştırması sınanmadı."},{id:"P04",title:"Wang, Wang & Gai · 2021 · Mental contrasting with planning",url:"https://pmc.ncbi.nlm.nih.gov/articles/PMC8149892/",type:"research",finding:"24 etki içeren 21 makalede, zihinsel karşılaştırmayı “şu olursa bunu yaparım” planıyla birleştirmek hedefe ulaşmada küçük ile orta arasında ortalama yarar gösterdi.",limitation:"Sonuçların farklılığı ve yayın yanlılığı işaretleri büyüklüğü sınırlar. Kısa ODA uyarlaması sınanmadı. Mümkün olmayan hedefleri bırakmak gerekebilir."},{id:"P05",title:"Rozental et al. · 2018 · Controlled procrastination interventions",url:"https://www.frontiersin.org/journals/psychology/articles/10.3389/fpsyg.2018.01588/full",type:"research",finding:"718 kişinin katıldığı 12 çalışmada, etkin müdahale almayan kontrollere göre kişinin bildirdiği ertelemede küçük bir ortalama azalma bulundu.",limitation:"Çoğunlukla öğrenciler, farklı yöntemler, kalite kaygıları ve her tedavide az çalışma vardı. Kesin olmayan bulgular ODA’nın etkisini veya evrensel bir tedavi sıralamasını göstermez."},{id:"P07",title:"Wohl, Pychyl & Bennett · 2010 · Self-forgiveness and procrastination",url:"https://www.researchgate.net/publication/222302476_I_forgive_myself_now_I_can_study_How_self-forgiveness_for_procrastinating_can_reduce_future_procrastination",type:"research",finding:"İki ara sınavdan önce değerlendirilen 119 birinci sınıf öğrencisinde, daha fazla kendini affetmek ile sonraki sınav için daha az ertelemek ilişkiliydi.",limitation:"Tek bir dersteki öğrenci grubunu izleyen gözlemsel bir çalışmadır. Hazır cümlenin nedensel etkisi veya tamamlanmış düzeltme gösterilmedi. Başta katılan ve çalışmadan ayrılan kişi sayıları doğrulanmadı."},{id:"P08",title:"Han & Kim · 2023 · Self-compassion intervention review",url:"https://pubmed.ncbi.nlm.nih.gov/37362192/",type:"research",finding:"56 rastgele kontrollü çalışmada, kendine şefkat uygulamalarının hemen sonrasında sıkıntı ölçülerinde küçük ile orta arasında yararlar görüldü. Bulguların sınırları vardı.",limitation:"Genel yanlılık riski yüksekti. Programlar farklı, etkin yöntemlerle karşılaştırmalar sınırlıydı. Tek bir cümlenin kaygıyı tedavi ettiğine veya ertelemeyi azalttığına dair burada kanıt yok."},{id:"P09",title:"Zhou et al. · 2026 · Planning and willingness to initiate",url:"https://pubmed.ncbi.nlm.nih.gov/41601124/",type:"research",finding:"81 lisans öğrencisiyle yapılan rastgele kontrollü çalışmada, olumlu düşünmeye göre MCII ile işin daha az itici geldiği ve harekete geçme isteğinin arttığı bildirildi.",limitation:"Çalışma Çin’de tek bir özel üniversitede yapıldı. Katılımcılar kısa süre izlendi. Özet, nesnel tamamlanmayı, günlük başlama yüzdelerini, ayrılan kişi sayısını veya ön kayıt durumunu doğrulamaz."},{id:"P10",title:"Oettingen et al. · 2015 · Time-management planning procedure",url:"https://www.socmot.uni-konstanz.de/sites/default/files/Oettingen_et_al-2015-European_Journal_of_Social_Psychology_0.pdf",type:"research",finding:"Akademik MCII alıştırmasında öğrenciler istedikleri sonucu, engeli ve ne yapacaklarını düşündü. Zaman ve yeri belirledi, prova yaptı, haftalık takvim hazırladı. Planlanan etkinlik saatleri ölçüldü.",limitation:"İlk çalışmada 84 Alman lisans öğrencisi rastgele gruplara ayrıldı. Tamamlanan iş değil, planlanan saatler ölçüldü. ODA bu alıştırmayı yetişkinlerin gündelik işleri için uyarlıyor."},{id:"P11",title:"Biwer et al. · 2023 · Fixed and self-regulated breaks",url:"https://pubmed.ncbi.nlm.nih.gov/36859717/",type:"research",finding:"87 öğrenciyle yapılan çalışmada, kendi seçtikleri molalar 24/6 ve 12/3 düzenleriyle karşılaştırıldı. Sabit düzenlerde kişilerin bildirdiği yararlar vardı. İşin tamamlanmasında istatistiksel olarak anlamlı fark bildirilmedi.",limitation:"Küçük bir örneklem, kendi kendine çalışılan tek bir günde incelendi. Yalnızca özete erişildi. İstatistiksel olarak anlamlı fark bulunmaması, eşit iş çıkarıldığını, ertelemenin kalıcı olarak azaldığını veya en iyi sürenin 25/5 olduğunu kanıtlamaz."},{id:"P12",title:"Albulescu et al. · 2022 · Micro-breaks review",url:"https://journals.plos.org/plosone/article?id=10.1371/journal.pone.0272460",type:"research",finding:"22 örneklemde kısa molaların yorgunluğu azaltma ve canlılığı artırma bakımından ortalama yararları, genel performans için bulunan yararlardan daha belirgindi.",limitation:"İşler ve mola etkinlikleri farklıydı. En iyi sürenin 25/5 olduğu veya zorlayıcı işlerde güvenilir performans artışı gösterilmedi."},{id:"P13",title:"Harkin et al. · 2016 · Progress monitoring meta-analysis",url:"https://pubmed.ncbi.nlm.nih.gov/26479070/",type:"research",finding:"138 rastgele kontrollü çalışmada, izleme uygulamaları hedefe ulaşmayı ortalama olarak artırdı.",limitation:"Hedefler ve yöntemler farklıydı. Kayıt ve bildirim analizleri her biçimin nedensel etkisini kanıtlamaz. Herkese açık paylaşım ve iki dakikalık haftalık düzen gerekmez."},{id:"P15",title:"Psychological Science · 2026 · Deadline-paper retraction",url:"https://journals.sagepub.com/doi/full/10.1177/09567976261488042",type:"guidance",finding:"2 Eylül duyurusu, verilerin güvenilirliği ve gerçekliğiyle ilgili kaygılar nedeniyle Ariely ve Wertenbroch’un 2002 teslim tarihi makalesini geri çekiyor.",limitation:"Geri çekilen sonuçlar bir tekniği destekleyemez. Duyuru, her kişisel kontrol noktasının veya teslim tarihinin etkisiz olduğunu göstermez."},{id:"procrastination-pomodoro",title:"Cirillo · Pomodoro Technique provenance",url:"https://www.pomodorotechnique.com/francesco-cirillo/",type:"technique",finding:"Geliştiricinin anlatısı, genellikle 25 dakikalık çalışma aralıkları ve kısa molalarla öğretilen zamanlayıcı düzenini açıklar.",limitation:"Uygulamanın kaynağını gösterir, bağımsız etkililik kanıtı değildir. Geliştiricinin bu anlatısı tam süreleri veya ODA düzenini doğrulamaz."},{id:"if-then-plans",title:"Gollwitzer & Sheeran · 2006 · If-then planning meta-analysis",url:"https://www.socmot.uni-konstanz.de/sites/default/files/06_Gollwitzer_Sheeran_Implementation_Intentions_And_Goal.pdf",type:"research",finding:"94 bağımsız testte, belirli “şu olursa bunu yaparım” planları hedefe ulaşmayı ortalama olarak artırdı. Bu eski derlemede standartlaştırılmış etki büyüklüğü d = 0,65’ti.",limitation:"Bulgular farklı hedeflerden ve eski çalışmalardan geliyor. Etki büyüklüğü, başarıda yüzde 65 artış demek değildir. Etki ertelemeye özgü de değildir. ODA’nın kısa iş alıştırması sınanmadı."},{id:"self-forgiveness",title:"Wohl, Pychyl & Bennett · 2010 · Self-forgiveness and procrastination",url:"https://www.researchgate.net/publication/222302476_I_forgive_myself_now_I_can_study_How_self-forgiveness_for_procrastinating_can_reduce_future_procrastination",type:"research",finding:"İki ara sınavdan önce değerlendirilen 119 birinci sınıf öğrencisinde, daha fazla kendini affetmek ile sonraki sınav için daha az ertelemek ilişkiliydi.",limitation:"Tek bir dersteki öğrenci grubunu izleyen gözlemsel bir çalışmadır. Hazır cümlenin nedensel etkisi veya tamamlanmış düzeltme gösterilmedi. Başta katılan ve çalışmadan ayrılan kişi sayıları doğrulanmadı."},{id:"procrastination-pomodoro-breaks",title:"Biwer et al. · 2023 · Fixed and self-regulated breaks",url:"https://pubmed.ncbi.nlm.nih.gov/36859717/",type:"research",finding:"87 öğrenciyle yapılan çalışmada, kendi seçtikleri molalar 24/6 ve 12/3 düzenleriyle karşılaştırıldı. Sabit düzenlerde kişilerin bildirdiği yararlar vardı. İşin tamamlanmasında istatistiksel olarak anlamlı fark bildirilmedi.",limitation:"Küçük bir örneklem, kendi kendine çalışılan tek bir günde incelendi. Yalnızca özete erişildi. İstatistiksel olarak anlamlı fark bulunmaması, eşit iş çıkarıldığını, ertelemenin kalıcı olarak azaldığını veya en iyi sürenin 25/5 olduğunu kanıtlamaz."},{id:"P18",title:"Breines & Chen · 2012 · Compassionate writing and repair motivation",url:"https://self-compassion.org/wp-content/uploads/publications/selfimp.motivation.pdf",type:"research",finding:"İkinci deneyde, kendilerine anlayışla yazan lisans öğrencileri hatayı düzeltme ve tekrarlamama isteğinin arttığını bildirdi.",limitation:"100 kişi alındı, 91’i analiz edildi. Tamamlanmış düzeltme, kalıcı değişim veya ertelemede azalma ölçülmedi. ODA ayrı bir davranışla düzeltme adımı ekler."}],m=[{schemaVersion:2,revision:2,id:"procrastination-1",courseId:"procrastination",locale:"tr",title:"Ertelediğin işin bedeli birikiyor",goal:"Beklemek gerekli mi, kontrol et. Ardından ertelediğin işte işe yarayan küçük bir adım at.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Masraf raporu hâlâ bekliyor. Bir kez daha ertelemek sana neye mal olacak?",reason:{id:"procrastination-1-delay-cost-reason",label:"Son ertelemenin bedeli neydi, o anda beklemen gerçekten gerekli miydi?",kind:"text",maxLength:160,optional:!0,suggestions:["Gereken bilgiye o anda ulaşamıyordum","Fişi girmedim, yapılacak iş daha da birikti","Dinlenme veya acil bakım sorumluluğu önce geldi"]},why:{id:"procrastination-1-why",label:"Bu iş neye yarıyor, ertelemek hangi bedeli getiriyor?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Erteleme, beklemenin işleri kötüleştireceğini düşündüğün hâlde yapmayı istediğin işi geciktirmektir. Ama dinlenmek, daha öncelikli bir sorumluluk veya eksik kaynaklar beklemeyi gerekli kılabilir. Kendine tembel demeden önce hangi durumda olduğuna bak. Her gecikme kaçınma değildir. O anda gerçekten yapabileceğin bir şey var mı, yoksa önce başka bir ihtiyaç mı karşılanmalı?","Bir açıklamaya göre, hoş gelmeyen işten kaçınca şimdi rahatlarsın, bedeli sonra ödersin. Bu bir model. Her gecikmeyi açıklamaz. Hissettiğin duyguyu veya somut engeli adlandır. Güvenli ve işe yarayan bir adım mümkünse rahatsızlık sürerken küçük bir işi yap. Rahatlamak şart değil. Burada sınadığın şey işe yarayan adımdır."],example:{title:"Selin elindeki bir fişi giriyor",text:"Saat 15.00. Selin iki fişi eksik olduğu için masraf raporunu erteliyor. Eksik fiş kuralını kontrol edip elindeki bir fişi giriyor. Utancı geçmiyor. Girdiği fişi ve yanıtsız kalan soruyu kaydediyor. Rapor henüz bitmedi. Ama artık her kısmı durmuş gibi davranmıyor. Eksik fişler hâlâ çözüm beklerken elindeki bir bilgi rapora girmiş oluyor."}},move:{invitation:"Ertelediğin işe uygun bir kayıt, bir cümle veya bilgi sorusu seç.",instructions:["Beklemek gerçek bir ihtiyacını koruyor mu, önce buna bak.","Örneği ancak kendi işine uyuyorsa seç."],prompts:[{id:"procrastination-1-0",label:"İşin hangi kısmı rahatsız ediyor, hangi kısmı gerçekten durmuş durumda?",kind:"text",maxLength:160,optional:!0}],suggestions:{action:["Masraf raporuma elimdeki bir fişi gir","Ertelediğim işe yarayacak bir cümle yaz","İşimi durduran bir kural hakkında soru sor"],minimum:["Elimdeki bir fişi rapora gir","İşe yarayan bir cümle yaz","Kuralla ilgili tek bir net soru gönder"],cue:["İşte sonraki molam bitince","Akşam yemeğinden sonra tabağımı kaldırınca","Anlamadığım bir kural işimi durdurunca"],place:["İşteki çalışma masamda","Evde, mutfak masamda","İlgili kişiyle güvenli mesajlaşma kanalında"],minutes:[2,5,1],fallback:["Önce elimde olan bir fişi kullan","Taslak bir cümle yaz, belirsiz kısmı işaretle","Gerekirse ulaşabildiğim başka bir ilgili kişiye sor"],observation:["Rapora girdiğim fiş","Yazdığım cümle ve belirsiz kısmı","Gönderdiğim kural sorusu ve varsa yanıt"],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1}],bundles:[{action:"Masraf raporuma elimdeki bir fişi gir",minimum:"Elimdeki bir fişi rapora gir",cue:"İşte sonraki molam bitince",place:"İşteki çalışma masamda",fallback:"Önce elimde olan bir fişi kullan",observation:"Rapora girdiğim fiş",minutes:2},{action:"Ertelediğim işe yarayacak bir cümle yaz",minimum:"İşe yarayan bir cümle yaz",cue:"Akşam yemeğinden sonra tabağımı kaldırınca",place:"Evde, mutfak masamda",fallback:"Taslak bir cümle yaz, belirsiz kısmı işaretle",observation:"Yazdığım cümle ve belirsiz kısmı",minutes:2},{action:"İşimi durduran bir kural hakkında soru sor",minimum:"Kuralla ilgili tek bir net soru gönder",cue:"Anlamadığım bir kural işimi durdurunca",place:"İlgili kişiyle güvenli mesajlaşma kanalında",fallback:"Gerekirse ulaşabildiğim başka bir ilgili kişiye sor",observation:"Gönderdiğim kural sorusu ve varsa yanıt",minutes:2,kind:"support"}]},suggested:{action:"Masraf raporuma elimdeki bir fişi gir",minimum:"Elimdeki bir fişi rapora gir",minutes:2,cueHint:"İşte sonraki molam bitince",placeHint:"İşteki çalışma masamda",obstacleHint:"Eksik bilgi veya işi bırakma isteği",fallbackHint:"Önce elimde olan bir fişi kullan",observationHint:"Rapora girdiğim fiş",requiresChoice:!0},stopRule:"Bu deneme için acil sağlık, güvenlik veya sözleşme yükümlülüklerini geciktirme.",accessibleAlternative:"Sana uygun yardımcı araçları kullan veya gereken bilgiyi sor. İş durmuşsa destek almayı seç."},result:{question:"Seçtiğin işe yarayan küçük adımı gerçekten yaptın mı?",observationPrompt:"Tam olarak ne yaptın? Hangi kısımda hâlâ ilerleyemiyorsun?"},judgment:{primary:{id:"procrastination-1-decision",scenario:"Selin’in iki boş dakikası ve rapor şablonu var. İki fiş eksik. Ama kurallar, elindeki fişleri girmesine izin veriyor.",question:"Hangi adım bu ertelemeyi ele alır?",options:[{id:"procrastination-1-sort",text:"Sonra raporu daha kolay hazırlamak için elindeki bütün fişleri önce tarih sırasına göre tek tek dizsin.",feedback:"Fişleri sıralamak sonra işe yarayabilir. Ama burada eldeki kayıtlar şimdiden girilebilir. Bütün düzenleme bitene kadar bekleme. Bir fişi şimdi gir, eksik fişler için gereken kuralı da öğren."},{id:"procrastination-1-enter",text:"Eksik fiş kuralını kontrol etsin. Utancı devam etse de elindeki tek bir fişi hemen rapora girsin.",feedback:"Bu adım belirsizliği ele alır, eldeki zamanda işin bir parçasını ortaya çıkarır. Utancın sürmesi, girilen fişi yok etmez. Ne değiştiğini ve hangi bilginin hâlâ gerektiğini kaydet."},{id:"procrastination-1-wait",text:"Raporun tamamını tek oturuşta bitirebilmek için yarına daha uzun ve kesintisiz bir çalışma zamanı ayırsın.",feedback:"Bitirmek için uzun zaman gerekebilir. Ama bu, bugünkü başlangıç fırsatını değerlendirmiyor. Şimdiki zamanı bir fiş için kullan. Sonra kalan iş için ayrıca uygun bir zaman ayır."}],bestOptionId:"procrastination-1-enter"}},carry:{takeaway:"Engeli adlandır, gerçek ihtiyaca bak. Sonra işe yarayan küçük bir adım at.",followUp:{questionId:"procrastination-1-return",question:"Seni durduran rahatsızlık mıydı, yoksa gereken bir şeye hâlâ ulaşamıyor muydun?",observationPrompt:"Tam olarak ne yaptın? Hangi kısımda hâlâ ilerleyemiyorsun?",adjustmentPrompt:"Bir şeyi değiştirecek olsan, sıradaki denemeyi hayatına nasıl daha iyi uydurursun?"}},goDeeper:{sections:[{heading:"Gecikme, kişiliğin hakkında bir hüküm değil",paragraphs:["Steel’in 2007 derlemesi, 216 çalışmadan 691 korelasyonu bir araya getirdi. İşin hoş gelmemesi, daha düşük öz denetim ve işi yapabileceğine daha az güvenmek ertelemeyle ilişkiliydi. Bu ilişkiler, senin gecikmene neyin neden olduğunu göstermez. Araştırmaların çoğunda öğrenciler vardı. Eski yaygınlık tahminleri de bugünkü toplumu temsil eden güncel oranlar değildir. Bunları kendine tanı koymak veya herkesin durumunu açıklamak için kullanma. [P01]","Çalışma niyetiyle ilişki negatif 0,03’tü. Belirsizlik aralığı sıfırı da içeriyordu. Bu sıfıra yakın ortalama, herkesin yeterli isteği, zamanı, desteği veya kaynağı olduğunu göstermez. Onun yerine kendi işine bak: yapılabilir bir adım var mı? Önce gelen bir sorumluluk, sana uygun düzenleme ihtiyacı veya durman için bir neden var mı? Sıradaki adımı bu gerçeklerden seç. Kişiliğine taktığın bir etiketle karar verme."]},{heading:"Şimdi rahatlamak, sonra bedel ödemek",paragraphs:["Sirois ve Pychyl bir duygu düzenleme açıklaması sunar: hoş gelmeyen iş kaçınmayı tetikleyebilir. Kaçınmak anlık rahatlama sağlayabilir. Gelecekteki sen ise bitmemiş işi üstlenir. 2013 tarihli makale kuramsal bir anlatı derlemesidir. Bu döngüyü veya bir tedaviyi rastgele gruplarla sınayan deney değildir. Duyguyu fark etmenin somut planlamadan daha iyi olduğunu da göstermez. Bu, bazı ertelemelere bakmak için bir açıklamadır. [P02]","Duyguyu adlandırıp küçük bir iş yapmak ODA’nın uyarlamasıdır. İtiraf yazman veya sonra daha sakin hissetmen gerekmez. Denemeni gündelik, güvenli bir işte tut. Bilgi eksikse net bir soru sormak faydalı adım olabilir. Dinlenme, korunma veya acil sorumluluk önce geliyorsa o seçimi dürüstçe kaydet. Sonraki dersler, gerçek denemelerine göre aynı planı geliştirir. Her gün yeni bir başarısızlık bulmanı istemez. Buradaki kayıt, kendi durumunu daha açık görmen içindir."]}],sourceIds:["P01","P02"]}},{schemaVersion:2,revision:2,id:"procrastination-2",courseId:"procrastination",locale:"tr",title:"Hazırlık yeter. İşe yarayan bir parça çıkar",goal:"Aynı işin kullanabileceğin küçük bir kısmını yap. Elindeki zamana göre nerede duracağını belirle.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Yine bütün zamanı hazırlanarak mı geçirdin? İşin kullanılabilir bir parçası elinde kalsın.",reason:{id:"procrastination-2-preparation-output-reason",label:"Son hazırlığından ne çıktı, işin hangi yararlı parçası hâlâ eksik?",kind:"text",maxLength:160,optional:!0,suggestions:["Malzemeler hazır ama henüz cümle yazmadım","Gerçekten eksik olan bir yönerge var","Bir fiş girdim, sıradaki hâlâ bekliyor"]},why:{id:"procrastination-2-why",label:"Kullanılabilir tek bir parça hangi işini kolaylaştırır?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Seçtiğin işi koru. Yapacağın işi ve elinde ne kalacağını söyle: bir fiş gir, bir cümle çevir veya gereken bir soruyu yanıtla. Dosyayı açmak hazırlıktır. Kullanılabilir bir parça eklemek işi yapmaktır. Hazırlık gerekli olabilir. O anki adımın buysa ona dürüstçe hazırlık de. Hazırladığın dosya ile içine eklediğin cümle aynı şey değil.","Belirli bir plan, uygun başlama anı geldiğinde ne yapacağını söyler. Araştırma bu genel yolu destekliyor. Tam iki dakikanın özel bir etkisi olduğunu göstermiyor. Elindeki zamana sığan büyüklüğü seç. Gerekirse orada dur. Başladıktan sonra da iş sana rahatsız edici gelebilir. Daha iyi hissetmeyi şart koşma. Ortaya çıkan işi kaydet."],example:{title:"Selin rapora bir fiş daha ekliyor",text:"Salı günü çay molasının ardından Selin’in aynı rapor için beş dakikası var. Fiş klasörlerini yeniden düzenlemeyi düşünüyor. Onun yerine bir fiş daha giriyor. Kategori belirsiz kalınca sormak için işaretliyor. Seçtiği süre dolduğunda duruyor. Artık iki fiş girilmiş durumda. Rapor henüz bitmiş değil. Hazırlığı büyütmek yerine mevcut zamana sığan bir kayıt ekledi."}},move:{invitation:"Kaydettiğin işi ve küçük adımı koru. Elindeki sürede işin kullanabileceğin bir kısmını tamamla.",instructions:["İşi koru. Başka bir küçük parça seçersen en küçük adımını değiştir.","“Engelle karşılaşınca” ve “Neye bakacaksın?” alanlarını seçtiğin işe göre düzenle."],prompts:[],suggestions:{action:["Masraf raporuma elimdeki bir fişi gir","Belgemden tek bir cümle çevir","İş için gereken bir soruyu yanıtla"],minimum:["Elimdeki bir fişi rapora gir","Tek bir cümlenin taslak çevirisini yap","İşe yarayan tek bir yanıt yaz"],cue:["İşte sonraki molam bitince","Bu işe ayırdığım sonraki zaman başlayınca","Akşam yemeğinden sonra tabağımı kaldırınca"],place:["İşteki çalışma masamda","Rahatça erişip kullanabildiğim çalışma masamda","Evde, mutfak masamda"],minutes:[2,5,10],fallback:["Klasörleri değiştirmeden sıradaki bir fişi rapora gir","Belirsiz terimi işaretle, cümleyi çevirip bitir","Bildiğim kısmı yaz, eksik bilgiyi birine sor"],observation:["Girdiğim fiş ve varsa belirsiz kalan kategori","Çevirdiğim cümle ve emin olmadığım terim","Yazdığım yanıt ve hâlâ eksik olan ayrıntı"],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1}],bundles:[{action:"Masraf raporuma elimdeki bir fişi gir",minimum:"Elimdeki bir fişi rapora gir",cue:"İşte sonraki molam bitince",place:"İşteki çalışma masamda",fallback:"Klasörleri değiştirmeden sıradaki bir fişi rapora gir",observation:"Girdiğim fiş ve varsa belirsiz kalan kategori",minutes:2},{action:"Belgemden tek bir cümle çevir",minimum:"Tek bir cümlenin taslak çevirisini yap",cue:"Bu işe ayırdığım sonraki zaman başlayınca",place:"Rahatça erişip kullanabildiğim çalışma masamda",fallback:"Belirsiz terimi işaretle, cümleyi çevirip bitir",observation:"Çevirdiğim cümle ve emin olmadığım terim",minutes:2},{action:"İş için gereken bir soruyu yanıtla",minimum:"İşe yarayan tek bir yanıt yaz",cue:"Akşam yemeğinden sonra tabağımı kaldırınca",place:"Evde, mutfak masamda",fallback:"Bildiğim kısmı yaz, eksik bilgiyi birine sor",observation:"Yazdığım yanıt ve hâlâ eksik olan ayrıntı",minutes:2}]},suggested:{action:"Masraf raporuma elimdeki bir fişi gir",minimum:"Elimdeki bir fişi rapora gir",minutes:2,cueHint:"İşte sonraki molam bitince",placeHint:"İşteki çalışma masamda",obstacleHint:"İşi yapmak yerine hazırlığını düzeltip duruyorum",fallbackHint:"Klasörleri değiştirmeden sıradaki bir fişi rapora gir",observationHint:"Girdiğim fiş ve varsa belirsiz kalan kategori"},stopRule:"Acil sorumluluklar veya güvensiz bir iş varsa dur. Gerekli iletişim ulaşılabilir kalsın.",accessibleAlternative:"Sesle yazdır, yaz, yardımcı araçlarını kullan veya eksik olan belirli bir kaynağı iste."},result:{question:"Seçtiğin kullanılabilir küçük parçayı gerçekten ortaya çıkardın mı?",observationPrompt:"Şimdi elinde hangi iş var, hangi kısmı yalnızca hazırlıktı?"},judgment:{primary:{id:"procrastination-2-decision",scenario:"Kerem’in randevusuna iki dakika var. Sözleşme dosyası hazır. Birinci bölümün hangi cümleyle başladığını biliyor.",question:"Hangi başlangıç eldeki iki dakikayı kullanır?",options:[{id:"procrastination-2-timer",text:"Sözleşmenin bütün çevirisini destekleyebilecek iki farklı zamanlayıcı ayarını karşılaştırıp daha sonra kullanacağı ayarı seçsin.",feedback:"Zamanlayıcı, sonraki çalışmayı düzenlemeye yardımcı olabilir. Ama ayar karşılaştırmak burada çeviri üretmez. Dosya ve ilk cümle hazır. Bu kısa fırsatı tek bir cümlenin taslak çevirisi için kullan."},{id:"procrastination-2-outline",text:"Sonraki çalışma daha az karışık gelsin diye sözleşmenin tamamını hangi sırayla çevireceğini ayrıntılı olarak planlasın.",feedback:"Nereden ilerleyeceğini bilmiyorsan plan gerekir. Kerem ise sıradaki cümleyi zaten biliyor. Bütün sırayı planlamak, şu an yapılabilecek küçük bir işi daha fazla hazırlıkla değiştirmiş olur."},{id:"procrastination-2-unit",text:"İlk cümleyi çevirsin, emin olmadığı bir terimi işaretlesin ve randevusuna yetişmek için zamanında çalışmayı bıraksın.",feedback:"Bu adım kullanılabilir bir taslak çıkarır ve belirsizliği gösterir. Sözleşmeyi bitirmiş gibi davranmaz. Kerem zamanında durabilir. İşaretlediği terimi sonraki çalışma zamanında ele almak için kaydında tutar."}],bestOptionId:"procrastination-2-unit"}},carry:{takeaway:"İşe yarayan bir parça üreten küçük başlangıç, işte gerçek ilerleme sağlar.",followUp:{questionId:"procrastination-2-return",question:"En küçük adımından yararlı bir parça çıktı mı, yoksa yerine hazırlık mı yaptın?",observationPrompt:"Şimdi elinde hangi iş var, hangi kısmı yalnızca hazırlıktı?",adjustmentPrompt:"Bir şeyi değiştirecek olsan, sıradaki denemeyi hayatına nasıl daha iyi uydurursun?"}},goDeeper:{sections:[{heading:"Başlangıç anını belirle. İki dakika şart değil",paragraphs:["Gollwitzer ve Sheeran’ın 2006 meta-analizi, “şu olursa bunu yaparım” planlarına dair 94 bağımsız testi birleştirdi. Bu planlar, tanınabilir bir durum ile önceden seçilmiş yanıtı belirtir. Farklı ortamlarda hedefe ulaşma ortalama olarak arttı. Tarihsel standartlaştırılmış etki 0,65’ti. Bu, başarıda yüzde 65 artış değildir. Senin sonucunu da önceden söylemez. Genel plan biçiminin desteğini, belirli bir kişiye verilmiş sonuç sözü gibi okumamak gerekir. [P03]","Bu ders, gündelik bir iş için başlama anı geldiğinde ne yapacağını önceden seçme yolunu kullanıyor. Kısa süre ve tek parça hedefi tasarım seçimleridir. Araştırmayla en iyi bulunmuş doz değildir. Küçük parça yine işe hizmet etmeli. Amacın yazmaksa yönerge okumak hazırlık, taslak cümle yazmak ise yazma işidir. İkisi de uygun olabilir. Adlarını ayrı tut. Gerçekten sahip olduğun süre dolunca dur. Daha sonra büyütüp büyütmemeye çıkan işe, erişime ve sorumluluklarına göre bak. Başlangıcın kolay hissettirmesi şart değil."]},{heading:"Süre tutmak isteğe bağlıdır",paragraphs:["Biwer ve arkadaşları, kişinin kendi seçtiği molaları iki düzenle karşılaştırdı: 24 dakika çalışma ve altı dakika mola; 12 dakika çalışma ve üç dakika mola. 87 öğrenci, tek bir kendi kendine çalışma gününde incelendi. Sabit düzenlerde daha az yorgunluk ve dikkat dağınıklığı gibi öznel yararlar vardı. İşin tamamlanmasında istatistiksel olarak anlamlı fark bildirilmedi. Bu, iki grubun eşit iş çıkardığını kanıtlamaz. [P11]","En fazla on dakikalık molaları inceleyen daha geniş derlemede, yorgunluk ve canlılık için yararlar genel performansa göre daha açıktı. En iyi düzenin 25/5 olduğunu göstermedi. [P12] Zamanlayıcı seçersen koşullarına uyan bir süre kullan. Gerçek işi yorgunluğunla birlikte değerlendir. Zamanlayıcının çalışması, işin yapılması değildir. Acil ve erişim için gereken iletişim açık kalsın. İhtiyaç duyduğun molaları ver. Bu dersi denemek için özel zamanlayıcı, satın alma veya bütün Pomodoro düzeni gerekmez."]}],sourceIds:["P03","P11","P12"]}},{schemaVersion:2,revision:2,id:"procrastination-3",courseId:"procrastination",locale:"tr",title:"İşten koptuğun o anı yakala",goal:"Aynı işte karşılaştığın engeli aşmak için seçtiğin adımı dene. Bu adıma ihtiyaç duyup duymadığını kaydet.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Dosyayı açar açmaz elin telefona mı gidiyor? Tam o an için plan yap.",reason:{id:"procrastination-3-switch-cost-reason",label:"Son kez işten uzaklaşınca ne kazandın, bunun bedeli ne oldu?",kind:"text",maxLength:160,optional:!0,suggestions:["Gerekli bir arama veya mesaj işi böldü","Kısaca rahatladım ama cümle yine yazılmadı","Eksik bir ayrıntı için bilgi sormam gerekiyordu"]},why:{id:"procrastination-3-why",label:"Bu işte kalmak senin için neyi korur?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Son iş kaydını kullan. İşten başka bir şeye geçtiğin anı bul: raporu açınca telefona uzanmak veya belirsiz bir kayıtta durmak gibi. O anda ne yapacağını belirlemek, “daha çok uğraşacağım” sözünden daha kolay sınanır. Daha önce seçtiğin küçük işi o anda yapmayı planla. Burada yeni bir iş aramıyoruz. Koptuğun belirli ana bakıyoruz.","İstenen sonucu bir engel ve “şu olursa bunu yaparım” yanıtıyla birleştiren araştırmalarda küçük ortalama yararlar var. Bu, uygulayacağını garanti etmez. Engel için uygun bir adım seç. Dikkat dağılması ortam değişikliği isteyebilir. Eksik bilgi için soru gerekir. Bakım sorumlulukları, hastalık veya güvensiz çalışma ise koşullarını uyarlamayı ya da destek almayı gerektirir."],example:{title:"Selin elinin telefona gittiğini fark ediyor",text:"Çarşamba rapor zamanı geldiğinde Selin dosyayı açıp telefona uzanıyor. Planı, telefonu ters çevirip önce bir fiş girmek. Bunu yapıyor. Ardından yanıtlaması gereken mesaja dönüyor. Bir fiş girdiğini ve engelin çıktığını kaydediyor. Aynı çalışma sırasında telefon daha sonra dikkatini yine dağıtıyor. O anda planını uygulaması, bütün dikkat sorununu çözdüğü anlamına gelmiyor."}},move:{invitation:"Kaydettiğin işi ve en küçük adımı koru. Karşılaştığın engel için seçtiğin adımı dene.",instructions:["“Engelle karşılaşınca” alanını, karşılaştığın engele göre değiştir.","Henüz kaydın yoksa tanıyabileceğin bir uzaklaşma veya eksik bilgi anını seç."],prompts:[],suggestions:{action:["Mesajlara bakmadan önce rapora bir fiş gir","Başka sekmeye geçmeden önce bir cümle yaz","Eksik bir ayrıntıyı öğrenmek için soru sor"],minimum:["Elimdeki bir fişi rapora gir","İşe yarayan bir cümle yaz","Tek bir konu hakkında net soru gönder"],cue:["Çalışırken elim telefona gidince","Başka sekmeye geçmek isteyince","Belirsiz bir kayıt ilerlememi durdurunca"],place:["İşteki çalışma masamda","Rahatça erişip kullanabildiğim çalışma masamda","İlgili kişiyle güvenli mesajlaşma kanalında"],minutes:[2,5,1],fallback:["Telefonu ters çevir, acil iletişimi açık tut","Ek sekmeleri kapalı tut, cümlenin taslağını yaz","Soruyu kullanabildiğim başka bir iletişim yoluyla gönder"],observation:["Engel çıktı mı, ne yaptım, hangi fişi girdim?","Sekmeye geçme isteğim, yaptığım adım ve yazdığım cümle","Belirsiz ayrıntı ve gerçekten gönderdiğim soru"],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1}],bundles:[{action:"Mesajlara bakmadan önce rapora bir fiş gir",minimum:"Elimdeki bir fişi rapora gir",cue:"Çalışırken elim telefona gidince",place:"İşteki çalışma masamda",fallback:"Telefonu ters çevir, acil iletişimi açık tut",observation:"Engel çıktı mı, ne yaptım, hangi fişi girdim?",minutes:2},{action:"Başka sekmeye geçmeden önce bir cümle yaz",minimum:"İşe yarayan bir cümle yaz",cue:"Başka sekmeye geçmek isteyince",place:"Rahatça erişip kullanabildiğim çalışma masamda",fallback:"Ek sekmeleri kapalı tut, cümlenin taslağını yaz",observation:"Sekmeye geçme isteğim, yaptığım adım ve yazdığım cümle",minutes:2},{action:"Eksik bir ayrıntıyı öğrenmek için soru sor",minimum:"Tek bir konu hakkında net soru gönder",cue:"Belirsiz bir kayıt ilerlememi durdurunca",place:"İlgili kişiyle güvenli mesajlaşma kanalında",fallback:"Soruyu kullanabildiğim başka bir iletişim yoluyla gönder",observation:"Belirsiz ayrıntı ve gerçekten gönderdiğim soru",minutes:2}]},suggested:{action:"Mesajlara bakmadan önce rapora bir fiş gir",minimum:"Elimdeki bir fişi rapora gir",minutes:2,cueHint:"Çalışırken elim telefona gidince",placeHint:"İşteki çalışma masamda",obstacleHint:"Çalışırken acil olmayan mesajlara bakmak için uzanıyorum",fallbackHint:"Telefonu ters çevir, acil iletişimi açık tut",observationHint:"Engel çıktı mı, ne yaptım, hangi fişi girdim?"},stopRule:"Acil iletişim ve erişim için gereken arama ve mesajları ulaşılabilir tut. Güvensiz veya erişilemeyen koşullarda destek seç.",accessibleAlternative:"Sana uygun bir hatırlatma kullan, gereken kaynağı iste veya açıkça hazırlık olarak kaydedeceğin bir prova yap."},result:{question:"Seçtiğin yanıtı kullanıp en küçük adımını gerçekten yaptın mı?",observationPrompt:"Engel çıktı mı, çıktığında tam olarak ne yaptın?"},judgment:{primary:{id:"procrastination-3-decision",scenario:"Ece tez dosyasını açınca telefona uzanıyor. İlk makale elinde. En küçük adımı taslak bir cümle yazmak. Acil bir arama veya mesaj beklemiyor.",question:"Bu engele hangi yanıt daha uygun?",options:[{id:"procrastination-3-response",text:"Telefonu kenara koysun. Makale hakkında taslak bir cümle yazsın. Ardından bakması gereken mesajları kontrol etsin.",feedback:"Bu plan, telefona uzandığı anda daha önce seçtiği küçük işi yapmasını sağlıyor. Sonrasında gerekli iletişime dönmesine izin veriyor. Başlangıç anını yakalayıp yakalamadığını ve gerçekten yazdığı cümleyi kaydetsin."},{id:"procrastination-3-later",text:"Hafta sonuna daha uzun bir çalışma ayırsın. Böylece bugünkü dikkat dağılması tez bölümünü daha az etkilesin.",feedback:"Hafta sonunda daha çok zaman genel olarak yardımcı olabilir. Ama şu an işten kopmasına yol açan anı değiştirmiyor. Daha büyük bir çalışma eklemeden önce bu anda uygulanabilir bir yanıtı dene."},{id:"procrastination-3-inspire",text:"Ne yazacağını seçmeden önce tez hedefini tekrar okusun ve bitmiş bölümün nasıl görüneceğini gözünde canlandırsın.",feedback:"Hedefi hatırlamak yön verebilir. Ece’nin ayrıca telefona uzandığı an için bir plana ve gerçekten yazacağı bir cümleye ihtiyacı var. Sadece düşünmek, o yanıtı bugün kullanıp kullanamadığını sınamaz. Somut deneme hâlâ bekler."}],bestOptionId:"procrastination-3-response"}},carry:{takeaway:"Engel çıktığında yapabileceğin bir adım seç. İşe yarayan bir sonuç veriyor mu, dene.",followUp:{questionId:"procrastination-3-return",question:"Engeli zamanında fark ettin mi, seçtiğin yanıtı o anda gerçekten kullanabilir miydin?",observationPrompt:"Engel çıktı mı, çıktığında tam olarak ne yaptın?",adjustmentPrompt:"Bir şeyi değiştirecek olsan, sıradaki denemeyi hayatına nasıl daha iyi uydurursun?"}},goDeeper:{sections:[{heading:"Engel için plan yapmak ne ekler?",paragraphs:["“Şu olursa bunu yaparım” planıyla birlikte zihinsel karşılaştırma, istediğin sonucu bir engel ve önceden planlanmış yanıtla birleştirir. Wang ve arkadaşları, 24 bağımsız etki içeren 21 makaleyi bir araya getirdi. Hedefe ulaşmada küçük ile orta arasında ortalama yarar buldular. Sonuçlar değişiyordu. Yayın yanlılığına işaret eden bulgular da vardı. Bu yaklaşım, mümkün olmayan bir hedefi bırakmaya da yardım edebilir. Her engeli aşma zorunluluğu değildir. [P04]","Oettingen ve arkadaşlarının 2015 akademik alıştırmasında öğrenciler önemli bir konuyu seçti. Sonucu ve engeli hayal etti, yanıt belirledi, zaman ve yer ekledi, prova yaptı, haftalık takvim hazırladı. Ölçülen şey tamamlanmış iş değil, planlanan çalışma saatleriydi. [P10] Gündelik bir iş için yaptığın kısa plan, bu uygulamayı değiştiriyor. Burada senden işin hangi kısmını yaptığını söylemen isteniyor. Hayal etmek, prova yapmak, planlamak ve işi yapmak birbirinin yerine geçmez. Bir planın beş plandan daha iyi olduğunun kanıtlandığını da varsayma."]},{heading:"Başlama isteği, başlanmış işin kanıtı değildir",paragraphs:["Zhou ve arkadaşlarının yakın tarihli rastgele kontrollü çalışması, Çin’de tek bir özel üniversitedeki 81 lisans öğrencisini kapsadı. Erişilebilir özette, planlama yönteminden sonra yalnızca olumlu düşünmeye göre işin daha az itici geldiği ve harekete geçme isteğinin arttığı bildiriliyor. Deney başlama isteğini ölçtü. Doğrulanmış iş başlangıçlarını veya tamamlanmayı değil. İstemeyi yapmakla aynı sayma. Bu ayrım, kendi kaydını okurken de geçerli. [P09]","Olumlu düşünceler kendiliğinden işe yaramaz sayılmaz. Engel de içindeki bir kusur olmak zorunda değil. Bu deneme, bildirdiğin işten uzaklaşma anından veya somut engelden başlar. İyi plan, bulunduğun ortamda ne zaman başlayacağını fark edip uygulayabildiğin plandır. Engel hiç çıkmadıysa yanıt sınanmamıştır. Başarısız sayılmaz. Engel çıkıp yanıt mümkün olmadıysa ortamı, büyüklüğü veya desteği değiştir. Aynı işi ve yönü koruyup kaydının gösterdiği koşulu değiştirmen yeterli."]}],sourceIds:["P04","P10","P09"]}},{schemaVersion:2,revision:2,id:"procrastination-4",courseId:"procrastination",locale:"tr",title:"Süre geçti mi? Düzeltebildiğin yerden dön",goal:"Tutamayacağın söz vermeden uygun bir düzeltme, işe dönüş veya destek adımı seç.",minutes:{learning:6,suggestedAction:5,review:2},direction:{hook:"Teslim günü geçti mi? Dürüst bir mesaj, bekleyen kişiye bundan sonra ne olacağını söyler.",reason:{id:"procrastination-4-owed-repair-reason",label:"Hangi kısmı düzeltmek senin sorumluluğun, yine susmanın veya söz vermenin bedeli ne olur?",kind:"text",maxLength:160,optional:!0,suggestions:["Bekleyen kişiye durum bilgisi vermem gerekiyor","Bilgi vermem gerekmiyor, işe geri döneyim","İletişim güvenli değil, önce destek isteyeyim"]},why:{id:"procrastination-4-why",label:"Şimdi hangi sorumluluğuna veya sınırına dikkat etmen gerekiyor?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["İş kaydını dürüst tut. Biri bekliyorsa ona bilgi vermen veya bir şeyi düzeltmen gerekip gerekmediğine bak. Neyin bitmediğini, neyi yapabileceğini açıkça söyle. Kendine anlayış göstermek teslim tarihini değiştirmez. Gecikmenin sonuçlarını silmez. Gücünün ötesinde söz vermeyi de haklı çıkarmaz. Dürüst bir mesaj, bekleyen kişinin şu anki durumu bilmesini sağlar.","Bir deneyde, anlayışlı yazmak kişilerin hatayı düzeltmek için bildirdiği isteği artırdı. Düzeltmenin yapılıp yapılmadığı ölçülmedi. Burada bu ayrımı kullan: kendine adil bir cümle söylemek hazırlıktır. Durumu bildirmek veya işin bir parçasını yapmak eylemdir. En küçük adımın tek bir iş olsun. Ek işleri ayrı kaydet. Kendini affetmiş hissetmen şart değil."],example:{title:"Selin neyin eksik olduğunu açıkça bildiriyor",text:"Perşembe sabahı Selin’in raporu gecikti. “Erteledim. Üzerime düşen kısmıyla ilgilenebilirim” diye yazıyor. Tek düzeltme adımı seçiyor: muhasebeye eksik fiş sorusunu ve kalan işi dürüstçe bildiren mesaj göndermek. Henüz yanıt gelmedi. Gönderdiği mesajı kaydediyor. Fiş girmek ayrı bir sonraki adım. Mesaj göndermiş olması, rapora fiş girdiği anlamına gelmiyor. Kaydı sadece yaptığı adımı anlatıyor."}},move:{invitation:"Aynı işin içinde kal. Sorumlu olduğun bir düzeltme, işe dönüş veya güvenli destek adımı seç.",instructions:["Adımı seçmeden önce hangi kısmı düzeltmenin gerçekten senin sorumluluğun olduğunu kontrol et.","En küçük adım olarak tek bir iş seç. Ek yaptıklarını ayrı kaydet."],prompts:[],suggestions:{action:["İşin yeni kapsamını ve uygun zamanını bildir","İşimde kullanabileceğim küçük bir parçayı yaz","Ertelediğim işi bölmek için yardım iste"],minimum:["İşin kapsamını ve zamanını dürüstçe bildiren mesaj gönder","İşimde kullanabileceğim tek bir cümle yaz","İşi bölmek için bir yardım isteği gönder"],cue:["İşte güvenle ara verebildiğim sonraki anda","Bu işe ayırdığım sonraki zaman başlayınca","Kararlaştırdığımız sonraki destek görüşmesi başlayınca"],place:["İşe uygun mesajlaşma kanalında","Rahatça erişip kullanabildiğim çalışma masamda","Güvenli destek mesajlaşma kanalında"],minutes:[5,2,10],fallback:["Belirsiz zaman için söz vermeden mevcut durumu bildir","Bildiğim kısmı yaz, eksik bir ayrıntıyı işaretle","Ulaşamıyorsam güvendiğim başka bir kişiden yardım iste"],observation:["Gönderdiğim durum bilgisi ve varsa gelen yanıt","İşim için yazdığım işe yarayan cümle","İşi bölmek için istediğim yardım ve varsa yanıt"],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1}],bundles:[{action:"İşin yeni kapsamını ve uygun zamanını bildir",minimum:"İşin kapsamını ve zamanını dürüstçe bildiren mesaj gönder",cue:"İşte güvenle ara verebildiğim sonraki anda",place:"İşe uygun mesajlaşma kanalında",fallback:"Belirsiz zaman için söz vermeden mevcut durumu bildir",observation:"Gönderdiğim durum bilgisi ve varsa gelen yanıt",minutes:5},{action:"İşimde kullanabileceğim küçük bir parçayı yaz",minimum:"İşimde kullanabileceğim tek bir cümle yaz",cue:"Bu işe ayırdığım sonraki zaman başlayınca",place:"Rahatça erişip kullanabildiğim çalışma masamda",fallback:"Bildiğim kısmı yaz, eksik bir ayrıntıyı işaretle",observation:"İşim için yazdığım işe yarayan cümle",minutes:2},{action:"Ertelediğim işi bölmek için yardım iste",minimum:"İşi bölmek için bir yardım isteği gönder",cue:"Kararlaştırdığımız sonraki destek görüşmesi başlayınca",place:"Güvenli destek mesajlaşma kanalında",fallback:"Ulaşamıyorsam güvendiğim başka bir kişiden yardım iste",observation:"İşi bölmek için istediğim yardım ve varsa yanıt",minutes:2,kind:"support"}]},suggested:{action:"İşin yeni kapsamını ve uygun zamanını bildir",minimum:"İşin kapsamını ve zamanını dürüstçe bildiren mesaj gönder",minutes:5,cueHint:"İşte güvenle ara verebildiğim sonraki anda",placeHint:"İşe uygun mesajlaşma kanalında",obstacleHint:"Sessiz kalmak veya tutamayacağım sözler vermek istiyorum",fallbackHint:"Belirsiz zaman için söz vermeden mevcut durumu bildir",observationHint:"Gönderdiğim durum bilgisi ve varsa gelen yanıt",requiresChoice:!0},stopRule:"Gündelik bir aksama seç. Başkasının verdiği zarar için kendini suçlama. İletişim güvenli değilse ara ver ve destek al.",accessibleAlternative:"Güvensiz iletişim yerine güvenli mesaj, yardımcı iletişim yöntemi veya destek seç."},result:{question:"Seçtiğin tek düzeltme veya işe dönüş adımını gerçekten yaptın mı?",observationPrompt:"Hangi tek adımı attın, işin hangi kısmı hâlâ bitmedi?"},judgment:{primary:{id:"procrastination-4-capacity-repair-decision",scenario:"Deniz söz verdiği taslağı yetiştiremedi. Ekibin durum bilgisine ihtiyacı var. Bugün tek bölüm verebilir. Bütün taslak için daha fazla zaman gerekiyor.",question:"Şu anki gücüne hangi yanıt uyar?",options:[{id:"procrastination-4-finish",text:"Önce yapabildiği bölümü bitirsin. Taslak güven verecek duruma gelene kadar ekibe bilgi vermek için beklesin.",feedback:"Bölümü hazırlamak önemli. Ama ekip zaten bekliyor ve güncel bilgiye ihtiyaç duyuyor. İşin kapsamını ve zamanını şimdi dürüstçe bildir. Ardından yapabildiğin bölümü hazırla. İkisini ayrı işler olarak kaydet."},{id:"procrastination-4-revise-first",text:"Şimdi bütün taslak için yeni tarih istesin. Bu tarih kabul edilene kadar yapabildiği bölümü de ertelesin.",feedback:"Yeni tarih konuşmak gerekli olabilir. Ama ekip bugün hem güncel bilgi hem kullanılabilir bölüm alabilir. Kalan iş için gerçekçi bir süre önerirken mevcut parçayı hazırla. Ekibin ihtiyacı beklemeyi gerektiriyorsa buna göre davran."},{id:"procrastination-4-repair",text:"Söz verdiği taslağı yetiştiremediğini söylesin. Yapabileceği kapsamı ve zamanı önersin. Sonra bugün verebileceği tek bölümü hazırlasın.",feedback:"Bu adım tutamayacağı yeni bir söz vermeden gecikmenin sonuçlarıyla ilgileniyor. Bilgi vermek ve bölüm hazırlamak somut işler. Kabul etmek hâlâ ekibin seçimi. Gelen yanıtı da dürüstçe kaydet."}],bestOptionId:"procrastination-4-repair"}},carry:{takeaway:"Kendine adil bir cümle söylemek düzeltmeyi destekler. Düzeltme, gerçekten yaptığın somut davranıştır.",followUp:{questionId:"procrastination-4-chosen-act-return",question:"Seçtiğin düzeltme, işe dönüş veya destek adımı o anki gücüne gerçekten uydu mu?",observationPrompt:"Gerçekte ne yaptın, hangi konuya hâlâ yanıt vermen gerekiyor?",adjustmentPrompt:"Bir şeyi değiştirecek olsan, sıradaki denemeyi hayatına nasıl daha iyi uydurursun?"}},goDeeper:{sections:[{heading:"Kendine anlayış göstermek ve hatayı düzeltmek ayrı şeyler",paragraphs:["Breines ve Chen’in 2012 deneyinde lisans öğrencileri, yakın zamanda yanlış buldukları bir davranışı anlattı. Ardından kendilerine anlayışla ve sıcak bir dille yazdı. Çalışmaya alınan 100 kişiden 91’i analize girdi. Anlayışlı yazan grup, karşılaştırma gruplarına göre telafi etme ve tekrardan kaçınma isteğini daha fazla bildirdi. Deney, özürlerin veya düzeltmelerin gerçekten yapıldığını göstermedi. Zamanla ertelemenin azaldığını da ölçmedi. İstek ile davranış ayrı sonuçlar olarak kalıyor. [P18]","Bu ders gündelik bir gecikme için daha kısa, adil bir cümle kullanıyor. Buna ayrıca seçilmiş bir davranış ekliyor. Bu, ODA uyarlamasıdır. Sınanan alıştırma değildir. Güvenli bir mesaj, hata düzeltme, kararlaştırılmış küçük iş, sana uygun düzenleme isteği veya uymayan planı durdurma seçebilirsin. Gerçek kayda hangi işin yapıldığını yaz. Sorumluluğun, gerçekten yaptığınla orantılı kalsın. Sana zarar verildiği için iletişim kurmak, barışmak veya özür dilemek zorunda değilsin."]},{heading:"Affetme bulgusu neyin sözünü vermez?",paragraphs:["Wohl, Pychyl ve Bennett, tek bir psikoloji dersindeki 119 birinci sınıf öğrencisini inceledi. Öğrenciler iki ara sınavın her birinden hemen önce değerlendirildi. Kendini daha fazla affetmek, ikinci sınavdan önce daha az ertelemeyle ilişkiliydi. Bu gözlemsel ilişki, değişime affetmenin neden olduğunu kanıtlamaz. Belirli bir hazır cümlenin birini işe döndürdüğünü de göstermez. Buradan senin nasıl hissedeceğini veya davranacağını önceden çıkaramayız. [P07]","Kendini affetmek ve kendine şefkat göstermek birbiriyle ilgili ama ayrı kavramlardır. Han ve Kim’in 56 rastgele kontrollü çalışmayı birleştiren derlemesinde sıkıntı ölçülerinde sınırlı yararlar bulundu. Genel yanlılık riski yüksekti. Tek bir cümleyi tedavi olarak doğrulamaz. Sonraki işe başlamanı kolaylaştırdığını da göstermez. [P08] Pişmanlık veya öfke sürerken adil bir anlatımı deneyebilirsin. Sınadığın şey, sonraki sözünün gerçeğe uyup uymadığı ve düzeltmenin veya işe dönüşün gerçekten olup olmadığıdır. Bunun için duygularının değişmesi gerekmiyor."]}],sourceIds:["P18","P07","P08"]}},{schemaVersion:2,revision:2,id:"procrastination-5",courseId:"procrastination",locale:"tr",title:"Başlamak yine aksadı mı? Haftaya uygun bir zaman seç.",goal:"İşe yarayan planını koru. Gördüğün tek engeli değiştir ve sıradaki uygun denemeyi planla.",minutes:{learning:6,suggestedAction:2,review:2},direction:{hook:"Bazı günler işe başladın, bazı günler başlayamadın mı? Gelecek haftanın planını kayıtlarına göre seç.",reason:{id:"procrastination-5-reason",label:"Bu iş hâlâ bu hafta ayıracağın zamana ve güce değer mi?",kind:"text",maxLength:160,optional:!0,suggestions:["Verdiğim sözü yerine getirmeye devam etmek","Tekrar tekrar aksayan planın bir kısmını değiştirmek","Sürekli karşılaştığım bir sorun için destek istemek"]},why:{id:"procrastination-5-why",label:"Bu iş hâlâ bu hafta ayıracağın zamana ve güce değer mi?",kind:"text",maxLength:300,optional:!0}},idea:{paragraphs:["Kaydettiğin işi, seçtiğin yönü, en küçük adımı ve denemeleri kullan. İlerlemeyi kontrol etmek hedeflere ulaşmayı ortalama olarak destekleyebilir. Planı, denemeyi ve kullanılabilir işi ayır. Kayıt yoksa ne olduğunu bilmiyoruz demektir. Ne başarısızlık ne başarıdır. Kayda yazmadığın bir gün için kendiliğinden sonuç çıkarma. Önce ne olduğunu söyle.","Yardımcı olanı koru, seni durduran tek bir koşulu değiştir. Kendi koyduğun kontrol noktası deneme olarak kalabilir. Başkasına söz verdiğin teslimi değiştirmek için konuşmak ve anlaşmak gerekir. Sıradaki küçük işi kaydet. ODA ertesi gün dönüşünü planlar. İşe yarayan bir başlangıç anı bilmiyorsan ilk uygun denemeyi seç. Gecikme kalıcı zarar veriyorsa denemeyle birlikte destek al."],example:{title:"Selin gelecek haftayı kaydına göre seçiyor",text:"Cuma günü Selin aynı rapora bakıyor: üç fiş girmiş, bir soru yanıtsız, ayırdığı bir zamanı kullanmamış. İşteki molalar uygundu. Geç akşamlar uymadı. Pazartesi moladan sonra sıradaki fiş için zaman seçiyor. Kime hâlâ bilgi vermesi gerektiğini kontrol ediyor. Rapor bitmedi. Yeni planını yaptıklarına ve yapamadıklarına göre kuruyor. Boşluğu başarı gibi yazmıyor."}},move:{invitation:"Kaydettiğin işi ve işe yarayan başlangıcı koru. İşi durduran koşulu değiştir.",instructions:["İşe yarayan başlangıç kaydın yoksa ilk uygun fırsatı belirle.","Sıradaki küçük işi kaydet. ODA ertesi gün dönüşünü planlar."],prompts:[],suggestions:{action:["Masraf raporuma elimdeki bir fişi gir","İşimde kullanabileceğim küçük bir parçayı yaz","Uymayan çalışma zamanını değiştirmek için yardım iste"],minimum:["Elimdeki bir fişi rapora gir","İşimde kullanabileceğim tek bir cümle yaz","Zamanı ayarlamak için yardım isteği gönder"],cue:["İşte sonraki uygun molam bitince","Yazmaya ayırdığım bir sonraki zaman başladığında","Zamanı konuşacağımız kararlaştırılmış görüşme başlayınca"],place:["İşteki çalışma masamda","Rahatça erişip kullanabildiğim çalışma masamda","Güvenli destek mesajlaşma kanalında"],minutes:[2,5,10],fallback:["Bunun yerine yarınki uygun iş molasında dene","Bunun yerine yarın yazmaya ayırdığım zamanda dene","Ulaşamıyorsam güvendiğim başka bir kişiye sor"],observation:["Girdiğim fiş ve çalışma koşullarının işe uyup uymadığı","Yazdığım cümle ve zamanın işe uyup uymadığı","Zaman ayarlama isteğim ve varsa gelen yanıt"],when:[{label:"Bugün",daysFromToday:0},{label:"Yarın",daysFromToday:1}],bundles:[{action:"Masraf raporuma elimdeki bir fişi gir",minimum:"Elimdeki bir fişi rapora gir",cue:"İşte sonraki uygun molam bitince",place:"İşteki çalışma masamda",fallback:"Bunun yerine yarınki uygun iş molasında dene",observation:"Girdiğim fiş ve çalışma koşullarının işe uyup uymadığı",minutes:2},{action:"İşimde kullanabileceğim küçük bir parçayı yaz",minimum:"İşimde kullanabileceğim tek bir cümle yaz",cue:"Yazmaya ayırdığım bir sonraki zaman başladığında",place:"Rahatça erişip kullanabildiğim çalışma masamda",fallback:"Bunun yerine yarın yazmaya ayırdığım zamanda dene",observation:"Yazdığım cümle ve zamanın işe uyup uymadığı",minutes:2},{action:"Uymayan çalışma zamanını değiştirmek için yardım iste",minimum:"Zamanı ayarlamak için yardım isteği gönder",cue:"Zamanı konuşacağımız kararlaştırılmış görüşme başlayınca",place:"Güvenli destek mesajlaşma kanalında",fallback:"Ulaşamıyorsam güvendiğim başka bir kişiye sor",observation:"Zaman ayarlama isteğim ve varsa gelen yanıt",minutes:2,kind:"support"}]},suggested:{action:"Masraf raporuma elimdeki bir fişi gir",minimum:"Elimdeki bir fişi rapora gir",minutes:2,cueHint:"İşte sonraki uygun molam bitince",placeHint:"İşteki çalışma masamda",obstacleHint:"Seçtiğim çalışma zamanı bana uygun olmayabilir",fallbackHint:"Bunun yerine yarınki uygun iş molasında dene",observationHint:"Girdiğim fiş ve çalışma koşullarının işe uyup uymadığı"},stopRule:"Gecikme hayatına zarar veriyorsa şimdi destek al. Acil sorumluluklar uygun ve zamanında adım gerektirir.",accessibleAlternative:"Yardımla çalışmayı, destek isteğini, uygulanabilir bir sınırı veya ara vermeyi seçebilirsin."},result:{question:"Seçtiğin bir sonraki küçük işi gerçekten yaptın mı?",observationPrompt:"Ne yaptın veya destek almak için ne istedin?"},judgment:{primary:{id:"procrastination-5-decision",scenario:"Nazan salı başvuru yazısına cümleler ekledi. Perşembe için ayırdığı zaman uygun değildi, çalışamadı. Önceden anlaştıkları gibi arkadaşının yazıyı okuyup yorum yapması işe yaradı. Başvurunun son tarihi değişmiyor.",question:"Gelecek hafta neyi korusun, neyi değiştirsin?",options:[{id:"procrastination-5-more",text:"Her planlı başlangıç için günlük bir kontrol zamanı ve net bir hedef belirlesin. Sonuçlarıyla daha erken yüzleşsin.",feedback:"Daha fazla kontrol noktası düzen katabilir. Ama kayıt, perşembe zamanının uygun olmadığını gösteriyor. Arkadaşının yazıyı okuyup yorum yapmasını sürdür. Her güne baskı eklemeden önce uygun olmayan zamanı değiştir."},{id:"procrastination-5-adjust",text:"Arkadaşının yazıyı okuyup yorum yapmasını sürdürsün. Perşembe işe başlayacağı anı değiştirsin. Gelecek hafta gerçek denemelerini ve yazdıklarını karşılaştırsın.",feedback:"Bu seçim işe yarayan koşulu korur. Başvurunun son tarihini de gözden kaçırmaz. Yeni kayıt hem denemeleri hem işe yarayan yazıyı göstermeli. Başkalarıyla kararlaştırdığın bir şey değişiyorsa onlarla konuş."},{id:"procrastination-5-remove",text:"Teslim tarihleri hakkındaki kanıt belirsizken kişisel kontrol noktalarını kaldırsın. Sadece başvurunun son tarihine göre çalışsın.",feedback:"Genel kanıt belirsiz olsa da Nazan, arkadaşının yorumlarının işe yaradığını gördü. Bu desteği kanıtlanmış bir çare saymadan denemeye devam et. Zaman sorununu doğrudan ele al."}],bestOptionId:"procrastination-5-adjust"}},carry:{takeaway:"İşe yarayan koşulu koru, aksayanı değiştir. Sıradaki denemeden gerçekten çıkan işi dürüstçe kaydet.",followUp:{questionId:"procrastination-5-work-or-support-return",question:"Sıradaki iş veya destek adımını seçtiğin uygun başlangıç anında gerçekten yaptın mı?",observationPrompt:"Hangi iş veya destek isteği oldu, seçtiğin başlangıç anı uygun muydu?",adjustmentPrompt:"Bir şeyi değiştirecek olsan, sıradaki denemeyi hayatına nasıl daha iyi uydurursun?"}},goDeeper:{sections:[{heading:"Yöntem biriktirmek yerine kaydını kullan",paragraphs:["Harkin ve arkadaşları, farklı hedeflerde ilerlemeyi izlemeye dair 138 rastgele kontrollü çalışmayı birleştirdi. İzlemeyi artıran uygulamalar hedefe ulaşmayı ortalama olarak artırdı. Ek analizlerde kayıt ve bildirim daha büyük etkilerle ilişkiliydi. Ama bu ilişkiler, her paylaşım biçiminin iyileşmeye neden olduğunu kanıtlamaz. Herkese açık paylaşım gerekmez. Bu planla ODA ertesi gün denemene bakman için tek bir zaman ayırır. İstersen kendi takviminde haftalık karşılaştırma için de zaman seçebilirsin. Burada ikinci bir randevu kaydedilmez. [P13]","Tarihini kaydettiğin denemelere bak. Seçtiğin başlama anı, küçük adım ve engel için yaptığın plan işi yapmana yardımcı oldu mu? Tek parçanın bitmesi bütün işin bitmesi değildir. Hiç çıkmayan engelin yanıtı henüz sınanmamıştır. Geçmişteki boşluklar görünür kalsın. Gelecek hafta sana uyan koşulu koru. Denemelerinde sorun çıkaran koşulu değiştir. İş artık sorumluluklarına veya seçtiğin yola hizmet etmiyorsa yeni teknik eklemek yerine konuşup yeniden anlaşmayı, ara vermeyi veya durmayı düşün."]},{heading:"Destek ve teslim tarihlerinde sınırları açık tut",paragraphs:["Rozental ve arkadaşlarının kontrollü derlemesi, çoğu öğrenci olan 718 kişinin katıldığı 12 çalışmayı kapsadı. Psikolojik uygulamalar, etkin müdahale almayan kontrol gruplarına göre kişinin bildirdiği ertelemeyi ortalama olarak azalttı. Ama kalite sorunları, farklı yöntemler ve her tedavi için az çalışma olması bulguları kesinleştirmiyor. Sonuçlar ODA’nın işe yaradığını veya her biçimin uzmanla uygulanması gerektiğini göstermez. Ertelemenin hayatındaki etkisi destek gerektiriyorsa bu denemeyle birlikte değerlendirme veya yardım alabilirsin. [P05]","Ariely ve Wertenbroch’un kişisel teslim tarihleriyle ilgili sık anılan makalesi, verilerin güvenilirliği ve gerçekliğiyle ilgili kaygılar nedeniyle Eylül 2026’da geri çekildi. Sonuçları bir tekniği doğrulayamaz. Duyuru, her kontrol noktasının işe yaramadığını da söylemez. [P15] Kendi koyduğun hatırlatmayı istersen deneyebilirsin. İşverene, müşteriye veya okula söz verdiğin teslim tarihi ise bağlayıcıdır. Değiştirmeden önce konuş ve anlaşma iste. Acil sağlık, güvenlik, yasal veya sözleşme sorumluluklarının yerine kendine koyduğun baskıyı geçirme."]}],sourceIds:["P13","P05","P15"]}}],d=[{id:"1552360708-ebcdf76845ac",alt:"Pencere kenarında düşünceli oturan kadın"},{id:"1448387473223-5c37445527e7",alt:"İlk basamağa adım atan bir ayak"},{id:"1553044020-8c90843adf96",alt:"Sarı yapışkan not kâğıtları ve bir kalem"},{id:"1778958619388-b529cc4e78e8",alt:"Pencere kenarında çay içen genç kadın"},{id:"1506784983877-45594efa4cbe",alt:"Açık planlama defterinin üzerinde duran kahve fincanı"}],t=[1,2,0,2,1],k=[3,3,3,3,3],o={id:"procrastination",title:"Yine mi erteledin? İşe yarayan bir parça çıkar",subtitle:"Ertelediğin tek iş. Beş derste işe başla, engelle ilgilen ve dürüst bir planla geri dön.",description:"Ertelediğin iş yüzünden kendini yargılamayı bırak. İşin kullanabileceğin küçük bir kısmını tamamla, önüne çıkan engeli kaydet. Haftanın ihtiyacına göre üzerine düşeni düzelt veya planını değiştir.",scope:"Gündelik erteleme için beceri eğitimi. Terapi değildir. Erteleme yoğun kaygı, uzun süren çökkünlük veya dikkat güçlükleriyle birlikte sürüyor ve hayatını belirgin biçimde etkiliyorsa bir uzmandan destek alabilirsin.",outcome:"İşe yarayan küçük bir parça, engel çıktığında ne yapacağın ve sıradaki uygun tarih.",photo:{id:"1758598304525-c2bc7aada66d",alt:"Bitkilerle çevrili bir masada dizüstü bilgisayarıyla çalışan kadın"},lang:"tr",lessons:m.map((a,n)=>{const e=a.judgment.primary,r=e.options.find(i=>i.id===e.bestOptionId),l=e.options.filter(i=>i.id!==e.bestOptionId);return l.splice(t[n],0,r),{id:a.id,schemaVersion:2,v2:a,title:a.title,minutes:a.minutes.learning,goal:a.goal,reading:a.idea.paragraphs,practice:[...a.move.instructions,"Buraya dönüp gerçekte ne olduğunu kaydet."].slice(0,k[n]),reflection:a.direction.reason.label,question:`${e.scenario} ${e.question}`,options:l.map(i=>i.text),correct:t[n],feedback:r.feedback,takeaway:a.carry.takeaway,sources:a.goDeeper.sourceIds,deeper:a.goDeeper.sections,example:a.idea.example,photo:d[n]}})};export{o as COURSE,m as LESSONS_V2,s as SOURCES};
